package ca.yorku.eecs3311.coursepilot.application.ai;
import com.fasterxml.jackson.annotation.JsonAlias; import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import java.util.List;
@JsonIgnoreProperties(ignoreUnknown=true) public record QuizGenerationLlmResponse(List<GeneratedQuestion> questions){public QuizGenerationLlmResponse{questions=questions==null?List.of():questions;} @JsonIgnoreProperties(ignoreUnknown=true) public record GeneratedQuestion(String type,String prompt,List<String> options,@JsonAlias({"correct_answer","correctAnswer"})String correctAnswer,@JsonAlias({"reference_answer","referenceAnswer"})String referenceAnswer,@JsonAlias({"source_ids","sourceIds","sourceIDs"})List<String> sourceIds){public GeneratedQuestion{options=options==null?List.of():options;sourceIds=sourceIds==null?List.of():sourceIds;}}}
